        for (int i = 0; i < n; i++) {
            types[i] = fs.nextInt();
        }

        @SuppressWarnings("unchecked")
        PriorityQueue<Item>[] byType = new PriorityQueue[t + 1];

        Comparator<Item> withinType = (a, b) -> {
            int cmp = Integer.compare(a.price, b.price);
            return cmp != 0 ? cmp : Integer.compare(a.id, b.id);
        };

        for (int i = 0; i < n; i++) {
            int price = fs.nextInt();
            int type = types[i];
            if (byType[type] == null) {
                byType[type] = new PriorityQueue<>(withinType);
            }
            byType[type].offer(new Item(type, price, i));
