        Comparator<Item> globalOrder = (a, b) -> {
            int cmp = Integer.compare(a.price, b.price);
            if (cmp != 0) return cmp;
            cmp = Integer.compare(a.type, b.type);
            return cmp != 0 ? cmp : Integer.compare(a.id, b.id);
        };

        PriorityQueue<Item> global = new PriorityQueue<>(globalOrder);
        for (int type = 1; type <= t; type++) {
            if (byType[type] != null) {
                global.offer(byType[type].peek());
            }
        }

        int c = fs.nextInt();
        long total = 0;

        for (int j = 0; j < c; j++) {
            int request = fs.nextInt();

            if (request == 0) {
                while (!global.isEmpty()) {
                    Item candidate = global.poll();
                    PriorityQueue<Item> queue = byType[candidate.type];

                    if (queue != null && queue.peek() == candidate) {
                        total += candidate.price;
                        queue.poll();
                        if (!queue.isEmpty()) {
