                if (queue != null && !queue.isEmpty()) {
                    Item sold = queue.poll();
                    total += sold.price;
                    if (!queue.isEmpty()) {
                        global.offer(queue.peek());
                    }
                }
            }
        }

        System.out.println(total);
    }
}
